from collections import OrderedDict


def run(inp):
    if not isinstance(inp, dict):
        raise ValueError('input must be an object')
    records = inp.get('records')
    labels = inp.get('labels')
    if not isinstance(records, list) or not isinstance(labels, list):
        raise ValueError('records and labels must be lists')
    top_n = inp.get('top_n')
    if top_n is not None:
        if isinstance(top_n, bool) or not isinstance(top_n, int) or top_n < 1:
            raise ValueError('top_n must be a positive integer')
    lab = {}
    for l in labels:
        if isinstance(l, dict) and 'id' in l:
            lab[l['id']] = l
    groups = OrderedDict()
    total = 0
    unmatched = []
    for r in records:
        if not isinstance(r, dict) or 'id' not in r:
            continue
        l = lab.get(r['id'])
        if l is None:
            unmatched.append(r['id'])
            continue
        if str(l.get('sentiment', '')).strip().lower() != 'complaint':
            continue
        theme = str(l.get('theme') or 'unknown').strip()
        total += 1
        groups.setdefault(theme, []).append(r)
    ranking = []
    for theme, rs in groups.items():
        custs = []
        for r in rs:
            c = r.get('customer')
            if c is not None and c not in custs:
                custs.append(c)
        dates = sorted(str(r.get('date')) for r in rs if r.get('date'))
        ranking.append({
            'theme': theme,
            'count': len(rs),
            'share': round(len(rs) / total, 3) if total else 0,
            'customers': sorted(custs),
            'dates': dates,
            'first_date': dates[0] if dates else None,
            'last_date': dates[-1] if dates else None,
            'record_ids': [r['id'] for r in rs],
        })
    ranking.sort(key=lambda x: (-x['count'], x['theme']))
    for i, x in enumerate(ranking, 1):
        x['rank'] = i
    if top_n:
        ranking = ranking[:top_n]
    out = {'ranking': ranking, 'total_complaints': total}
    if unmatched:
        out['unlabelled_record_ids'] = unmatched
    return out

